from collections import deque

def find_connected_components(points, tolerance=1):
    """Find spatially connected groups of points"""
    if not points:
        return []

    grid_map = set(points)
    visited = set()
    components = []

    for start in points:
        if start in visited:
            continue

        component = []
        queue = deque([start])
        visited.add(start)

        while queue:
            curr = queue.popleft()
            component.append(curr)

            # Check 8-connected neighbors within tolerance
            for dr in range(-tolerance, tolerance+1):
                for dc in range(-tolerance, tolerance+1):
                    if dr == 0 and dc == 0:
                        continue
                    neighbor = (curr[0] + dr, curr[1] + dc)
                    if neighbor in grid_map and neighbor not in visited:
                        visited.add(neighbor)
                        queue.append(neighbor)

        components.append(sorted(component))

    return components

